const shell = 80;
const sections = [300, 600, 450];
const chunks = [{ at: shell, label: 'shell' }];
for (const s of sections) chunks.push({ at: shell + s, label: 'section@' + s });
chunks.sort((a, b) => a.at - b.at);
const ttfb = chunks[0].at;
const fullRender = chunks[chunks.length - 1].at;
const blockingTtfb = shell + Math.max(...sections);
console.log('order=' + chunks.map(c => c.label + ':' + c.at).join(','));
console.log('streaming TTFB=' + ttfb + 'ms');
console.log('full render=' + fullRender + 'ms');
console.log('blocking SSR TTFB=' + blockingTtfb + 'ms');
console.log('TTFB saved=' + (blockingTtfb - ttfb) + 'ms');
